void ssd1306DrawAnimationFrame(uint8_t frame_idx) {
    if (frame_idx >= LOGO_LETI_FRAMES_COUNT) frame_idx = 0;

    for (uint8_t page = 0; page < 8; page++) {
        ssd1306SetCursor(page, 0);
        i2cWriteRegister(SSD1306_ADDR, SSD1306_DATA, (uint8_t*)logo_leti_animation[frame_idx][page], 128);
    }
}

void play_leti_rotation(uint32_t frame_delay_ms) {
    for (uint8_t f = 0; f < LOGO_LETI_FRAMES_COUNT; f++) {
        ssd1306DrawAnimationFrame(f);
        delay_ms(frame_delay_ms);
    }
}
